class Position:
    def __init__(self, isin, nom, quantite, pru, cours):
        self.isin = isin
        self.nom = nom
        self.quantite = quantite
        self.pru = pru
        self.cours = cours          # passe par le setter → validation dès l'init

    @property
    def cours(self):
        return self._cours

    @cours.setter
    def cours(self, valeur):
        if valeur <= 0:
            raise ValueError(f"cours invalide : {valeur}")
        self._cours = valeur

    @property
    def valeur(self):
        return self.quantite * self._cours

    @property
    def plus_value_eur(self):
        return (self._cours - self.pru) * self.quantite

    @property
    def plus_value_pct(self):
        return (self._cours - self.pru) / self.pru * 100

    def __repr__(self):
        return f"Position({self.nom!r}, {self.quantite} × {self._cours} €)"


p = Position("IE00B4L5Y983", "IWDA", 50, 80.0, 92.5)
print(f"{p.valeur:.2f} €")            # 4625.00 €
print(f"{p.plus_value_eur:+.2f} €")   # +625.00 €
print(f"{p.plus_value_pct:+.1f} %")   # +15.6 %
p.cours = 95.0                        # OK
# p.cours = -3                        # ValueError: cours invalide : -3
```

Deux idées à retenir :

- `self.cours = cours` **dans `__init__`** passe déjà par le setter : la validation est centralisée en un seul endroit, impossible de construire une position invalide.
- Les appelants écrivent `p.valeur` comme un attribut : si demain la valeur vient d'une API temps réel, l'interface ne change pas — c'est exactement le contrat que C++/Java obtiennent avec des getters, sans la verbosité.

