class Frigo:
    def __init__(self):
        self._contenu = {}

    def ajouter(self, nom, qte):
        self._contenu[nom] = self._contenu.get(nom, 0) + qte

    def retirer(self, nom, qte):
        disponible = self._contenu.get(nom, 0)
        if disponible < qte:
            raise ValueError(
                f"impossible de retirer {qte} {nom} : {disponible} disponible(s)"
            )
        self._contenu[nom] = disponible - qte
        if self._contenu[nom] == 0:
            del self._contenu[nom]

    def __contains__(self, nom):
        return nom in self._contenu

    def __len__(self):
        return len(self._contenu)

    def __repr__(self):
        return f"Frigo({len(self)} ingrédients)"


frigo = Frigo()
frigo.ajouter("oeufs", 6)
frigo.ajouter("lait", 1)
frigo.ajouter("oeufs", 6)
print("oeufs" in frigo, len(frigo))   # True 2
frigo.retirer("oeufs", 12)
print("oeufs" in frigo)               # False
frigo.retirer("lait", 5)              # ValueError: impossible de retirer 5 lait : 1 disponible(s)
```

L'intérêt des dunders est dans le code **appelant** : `"oeufs" in frigo` se lit comme la question qu'on se pose, au lieu de `frigo.contient("oeufs")`. La classe encapsule par ailleurs les invariants (jamais de quantité négative, jamais de clé à 0) qu'un dict nu ne garantissait pas à l'exercice 2 du chapitre précédent — c'est exactement le passage « données brutes → objet métier ».

